  1988  static int parse_tables(struct archive_read* a, struct rar5* rar,
  1989          const uint8_t* p)
  1990  {
  1991      int ret, value, i, w, idx = 0;
  1992      uint8_t bit_length[HUFF_BC],
  1993          table[HUFF_TABLE_SIZE],
  1994          nibble_mask = 0xF0,
  1995          nibble_shift = 4;
  1996
  1997      enum { ESCAPE = 15 };
