  2049          ret = decode_number(a, &rar->cstate.bd, p, &num);
  2050          if(ret != ARCHIVE_OK) {
  2051              archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
  2052                      "Decoding huffman tables failed");
  2053              return ARCHIVE_FATAL;
  2054          }
