  2066              if(ARCHIVE_OK != read_bits_16(rar, p, &n))
  2067                  return ARCHIVE_EOF;
  2068
  2069              if(num == 16) {
  2070                  n >>= 13;
  2071                  n += 3;
  2072                  skip_bits(rar, 3);
  2073              } else {
  2074                  n >>= 9;
  2075                  n += 11;
  2076                  skip_bits(rar, 7);
  2077              }
