  2098          if(num == 18) {
  2099              n >>= 13;
  2100              n += 3;
  2101              skip_bits(rar, 3);
  2102          } else {
  2103              n >>= 9;
  2104              n += 11;
  2105              skip_bits(rar, 7);
  2106          }
